/**
 * dsh-ui-restart browser half — generated by dsh-ui-suite/scripts/build.mjs.
 *
 * One component per package: the runtime below is the same code every suite
 * package carries, so installing this package alone works, and the component
 * mounts under the same failure boundary as the rest of the suite.
 *
 * Edit src/component.js (or the runtime in dsh-ui-copy/src/core), then rerun
 * the build.
 */

/**
 * dsh-ui-copy runtime — the one place where a component gets its services.
 *
 * The suite exists because a dozen UI plugins used to poll the same document
 * with a dozen MutationObservers, each injecting its own <style> and each
 * guessing whether the shipped DOM had already mounted. This runtime gives them
 * one observer, one frame budget, one style registry and one failure boundary:
 *
 *   - `observe(pass)` registers a DOM pass; every registered pass runs in a
 *     single rAF-throttled sweep, and one crashing pass never stops the rest.
 *   - `style(id, css)` registers a sheet by component id, so a sheet can be
 *     replaced without touching the DOM and no sheet is ever written twice.
 *   - `mount(key, factory)` calls a component factory under `try`/`catch`, so a
 *     host upgrade that removes a slot, or a disabled external bundle, disables
 *     one component instead of the whole suite.
 *   - `option(name, fallback)` reads the config the host half injected, which is
 *     the only channel a browser bundle has: a boot-graph row arrives as
 *     `{ id, url, rev }` and `apply(ctx, config)` always sees an empty config.
 *
 * Component contract — a component is a top-level function in the built bundle:
 *
 *     function dshuiComponent_<key>(rt) {
 *       if (rt.config.enabled === false) return
 *       ...
 *     }
 *
 * Components never touch `window.__ModuleLoader__`, never build their own
 * MutationObserver, and never write a literal colour, radius, gap, size,
 * duration or shadow: those live in `lib/styles/tokens.css` as `--dshui-*`.
 */

/**
 * Build the runtime handed to every component.
 *
 * @param env - `{ ctx, require }` from the bundle factory.
 * @param config - the host half's injected `window.__DSHUI_CONFIG__` object.
 */
function dshuiCreateRuntime(env, config) {
  var ctx = env.ctx
  var load = env.require
  // The token contract lives on `body` (see lib/styles/tokens.css), so a token
  // is read there rather than from the document root.
  var root = document.body !== null ? document.body : document.documentElement
  var suiteConfig = isRecord(config) ? config : {}

  /** Component state: key -> `{ enabled, options }`. */
  var components = Object.create(null)

  /** Every DOM pass registered by an enabled component. */
  var passes = []

  /** Owned cleanups, run by `dispose`. */
  var cleanups = []

  /** A frame has been requested but has not run yet. */
  var scheduled = false

  function isRecord(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value)
  }

  function merge(base, over) {
    var out = {}
    var key
    for (key in base) if (Object.prototype.hasOwnProperty.call(base, key)) out[key] = base[key]
    for (key in over) if (Object.prototype.hasOwnProperty.call(over, key)) out[key] = over[key]
    return out
  }

  /**
   * A component key as the schema spells it: `session-delete` -> `sessionDelete`.
   *
   * Component ids stay hyphenated (they match `<nn>-<key>.js` and the sheet
   * names), while the host schema uses camelCase field names, so every lookup
   * tries both spellings rather than making each component remember which one
   * its block landed under.
   */
  function schemaKeyOf(key) {
    return String(key).replace(/-([a-z0-9])/g, function (_, letter) {
      return letter.toUpperCase()
    })
  }

  /**
   * The config block for one component.
   *
   * Accepts both shapes a config can arrive in — a flat `{ quota: { … } }` map
   * and the same value nested under `components` — and both spellings, because
   * the host half writes camelCase while components name themselves with
   * hyphens.
   */
  function componentConfig(key) {
    var names = [key, schemaKeyOf(key)]
    var found = null
    for (var index = 0; index < names.length; index += 1) {
      if (isRecord(suiteConfig[names[index]])) {
        found = suiteConfig[names[index]]
        break
      }
    }
    var nestedSource = isRecord(suiteConfig.components) ? suiteConfig.components : null
    var nested = null
    if (nestedSource !== null) {
      for (var position = 0; position < names.length; position += 1) {
        if (isRecord(nestedSource[names[position]])) {
          nested = nestedSource[names[position]]
          break
        }
      }
    }
    return merge(nested || {}, found || {})
  }

  function warn(key, message) {
    console.warn('[ui-copy/' + key + '] ' + message)
  }

  function fail(key, error) {
    console.error('[ui-copy/' + key + ']', error)
  }

  function request() {
    if (scheduled) return
    scheduled = true
    requestAnimationFrame(run)
  }

  function run() {
    scheduled = false
    if (document.body === null) return
    var snapshot = passes.slice()
    for (var index = 0; index < snapshot.length; index += 1) {
      var entry = snapshot[index]
      if (entry === undefined) continue
      try {
        entry.pass()
      } catch (error) {
        fail(entry.key, error)
        var position = passes.indexOf(entry)
        if (position !== -1) passes.splice(position, 1)
      }
    }
  }

  function sheetById(id) {
    return document.head.querySelector('style[data-dshui-sheet="' + String(id).replace(/["\\]/g, '\\$&') + '"]')
  }

  function installStyle(id, css) {
    var existing = sheetById(id)
    if (existing !== null) {
      existing.textContent = css
      return function () {
        if (existing.parentNode !== null) existing.parentNode.removeChild(existing)
      }
    }
    var style = document.createElement('style')
    style.setAttribute('data-dshui-sheet', id)
    style.textContent = css
    document.head.appendChild(style)
    return function () {
      if (style.parentNode !== null) style.parentNode.removeChild(style)
    }
  }

  function requireExternal(name) {
    try {
      return load(name)
    } catch (error) {
      fail('bundle', 'cannot load "' + name + '": ' + String((error && error.message) || error))
      return null
    }
  }

  /** The object handed to one component factory. */
  function componentApi(key, options) {
    return {
      /* ---- identity -------------------------------------------------- */
      key: key,
      ctx: ctx,
      suite: suiteConfig,

      /* ---- configuration --------------------------------------------- */
      /** This component's own block. `enabled` is already honoured by `mount`. */
      config: options,
      option: function (name, fallback) {
        var value = options[name]
        return value === undefined ? fallback : value
      },
      /** Another component's state, for components that depend on a sibling. */
      component: function (other) {
        return components[other] || { enabled: false, options: {} }
      },
      /** The current theme name, read from the same attribute the host themes on. */
      theme: function () {
        return document.body !== null && document.body.hasAttribute('data-ds-dark-theme') ? 'dark' : 'light'
      },

      /* ---- host services --------------------------------------------- */
      /** An external package, or `null` when it is not in this boot graph. */
      require: requireExternal,
      /** Run a host effect, or run the body directly when the seam is absent. */
      effect: function (body, label) {
        try {
          if (ctx && typeof ctx.effect === 'function') return ctx.effect(body, label || key)
        } catch (error) {
          fail(key, error)
          return undefined
        }
        try {
          return body()
        } catch (error) {
          fail(key, error)
          return undefined
        }
      },

      /* ---- document --------------------------------------------------- */
      /** Register a DOM pass; returns an unsubscribe function. */
      observe: function (pass) {
        var entry = { key: key, pass: pass }
        passes.push(entry)
        if (document.body !== null) request()
        return function () {
          var index = passes.indexOf(entry)
          if (index !== -1) passes.splice(index, 1)
        }
      },
      /** Ask for one sweep on the next frame. */
      schedule: request,
      /** Install or replace a sheet scoped to this component. */
      style: function (id, css) {
        return installStyle(key + '/' + id, css)
      },
      /** Current text of one of this component's sheets. */
      styleText: function (id) {
        var style = sheetById(key + '/' + id)
        return style === null ? '' : style.textContent
      },
      /** A token's computed value; components should prefer the CSS variable. */
      token: function (name, fallback) {
        try {
          var scope = document.body !== null ? document.body : root
          var value = getComputedStyle(scope).getPropertyValue(name).trim()
          if (value !== '') return value
        } catch (error) {
          fail(key, error)
        }
        return fallback === undefined ? '' : fallback
      },

      /* ---- diagnostics ------------------------------------------------ */
      log: function (message) {
        console.info('[ui-copy/' + key + '] ' + message)
      },
      warn: function (message) {
        warn(key, message)
      },
      error: function (error) {
        fail(key, error)
      },
    }
  }

  /**
   * Register a component and hand it the runtime.
   *
   * Enabled is the config's `enabled` when it is a boolean and `true` when the
   * profile says nothing, so a component that ships enabled keeps working after
   * an upgrade that adds a sibling and the user turns things off one by one.
   */
  function mount(key, factory) {
    var options = componentConfig(key)
    var record = {
      key: key,
      enabled: options.enabled === false ? false : true,
      options: options,
    }
    components[key] = record
    if (!record.enabled) return
    if (typeof factory !== 'function') {
      warn(key, 'no factory for this component')
      return
    }
    try {
      factory(componentApi(key, options))
    } catch (error) {
      record.enabled = false
      fail(key, error)
    }
  }

  var observer = null
  if (typeof MutationObserver === 'function') {
    observer = new MutationObserver(request)
    var start = function () {
      if (document.body === null) return
      // No `attributes`: React churns attributes constantly, and a component
      // that writes an attribute from a pass would re-enter itself through the
      // observer. Every surface this suite patches is created or replaced as a
      // node, so childList plus characterData is the whole trigger set.
      observer.observe(document.body, { childList: true, subtree: true, characterData: true })
      request()
    }
    if (document.body !== null) start()
    else document.addEventListener('DOMContentLoaded', start, { once: true })
    cleanups.push(function () {
      observer.disconnect()
    })
  }

  /** Remove every pass, sheet and observer this runtime owns. */
  function dispose() {
    passes.length = 0
    for (var index = 0; index < cleanups.length; index += 1) {
      try {
        cleanups[index]()
      } catch (error) {
        /* a failed cleanup must not stop the rest */
      }
    }
    cleanups.length = 0
  }

  var base = componentApi('runtime', {})
  return {
    ctx: ctx,
    config: suiteConfig,
    require: requireExternal,
    mount: mount,
    component: base.component,
    observe: base.observe,
    schedule: base.schedule,
    style: base.style,
    token: base.token,
    theme: base.theme,
    dispose: dispose,
  }
}

/* ---- component -------------------------------------------------------- */

/**
 * Restart control: one row inside the account menu at the sidebar foot, above
 * Settings, that fully quits and relaunches the DSH desktop app.
 *
 * Why the account menu rather than a corner seat: the frame's top-right corner
 * is shared with the right rail's control group. A seat there has to re-measure
 * that group on every layout change and still lands on top of it while the rail
 * slides, so the control is parked in the one surface whose rows the host lays
 * out itself.
 *
 * Why injection: the menu's rows come from a fixed list inside the host's
 * account surface and no slot is declared for them, so the row is cloned from
 * the Settings row of the open menu instead of registered into it. The menu is
 * rebuilt on every open, which makes one injection per open the whole
 * lifecycle: no teardown, no stale node.
 *
 * The row owns no restart logic. It posts the current session id to the host
 * half and waits: roughly a second later the whole app goes away, so the only
 * durable state is the host's pending-session file.
 */
function dshuiComponent_restart(rt) {
  /** Locale namespace for this component's copy. */
  const NS = 'dsh-restart'

  /**
   * Host route that schedules the quit-and-relaunch.
   *
   * The suite namespaces its host routes, so the old standalone spelling stays
   * registered on the host half as an alias: a page cached from before the
   * migration keeps working until it is reloaded.
   */
  const RESTART_ROUTE = '/dsh-ui-copy/restart'

  /** Copy, in the shape `ctx.locale.register` takes. */
  const zh = {
    'menu.label': '重启',
    'menu.pending': '正在关闭并重新启动…',
    'failed.network': '请求发不出去，重启未开始。',
    'failed.desktop': '当前不是桌面应用宿主，无法重启。',
    'failed.generic': '重启失败，请重试。',
  }
  const en = {
    'menu.label': 'Restart',
    'menu.pending': 'Quitting and relaunching…',
    'failed.network': 'The request could not be sent; nothing was restarted.',
    'failed.desktop': 'This process is not the desktop app host, so it cannot restart.',
    'failed.generic': 'Restart failed. Try again.',
  }

  /**
   * Stylesheet for the injected row. Everything that can come from the cloned
   * host row does; only the three spans and the busy state are owned here.
   */
  const STYLESHEET = `
.dsh-restart-row { display: flex; align-items: center; gap: 8px; width: 100%; }
.dsh-restart-row-icon { display: inline-flex; flex: none; align-items: center; justify-content: center; width: 16px; height: 16px; color: inherit; }
.dsh-restart-row-label { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: inherit; font-size: inherit; font-weight: inherit; }
.dsh-restart-row[aria-disabled="true"] { opacity: .6; }
.dsh-restart-row-spin { animation: dsh-restart-spin .9s linear infinite; }
@keyframes dsh-restart-spin { to { transform: rotate(360deg); } }
`

  /** What the row should read right now: idle, busy, or holding an error. */
  const state = { phase: 'idle', error: null }

  /**
   * Row labels. A row may be a real `menuitem`, a plain button or a link: the
   * menu surfaces differ between the web app and the desktop shell, so the text
   * is what identifies a row, not its role.
   */
  const SIGN_OUT = /^(退出登录|Sign out)/
  const SETTINGS_ROW = /^(设置|Settings)/

  /** Trim whitespace runs so a row's text reads as one line. */
  function rowText(row) {
    return (row.textContent ?? '').replace(/\s+/g, ' ').trim()
  }

  /** The open account menu: one holding a sign-out row, else a settings row. */
  function findAccountMenu() {
    const menus = document.querySelectorAll('[role="menu"]')
    for (const menu of menus) {
      for (const row of menu.querySelectorAll('[role="menuitem"], button, a')) {
        if (SIGN_OUT.test(rowText(row))) return menu
      }
    }
    for (const menu of menus) {
      for (const row of menu.querySelectorAll('[role="menuitem"], button, a')) {
        if (SETTINGS_ROW.test(rowText(row))) return menu
      }
    }
    return null
  }

  /**
   * The row this one sits above: Settings where the build puts it in the menu,
   * otherwise the menu's first row so the entry still lands inside the menu.
   */
  function findAnchorRow(menu) {
    for (const row of menu.querySelectorAll('[role="menuitem"]')) {
      if (SETTINGS_ROW.test(rowText(row))) return row
    }
    for (const row of menu.querySelectorAll('button, a')) {
      if (SETTINGS_ROW.test(rowText(row))) return row
    }
    return menu.querySelector('[role="menuitem"], button, a')
  }

  /** A circular-arrow glyph as a DOM node, for the row built outside React. */
  function glyphNode() {
    const ns = 'http://www.w3.org/2000/svg'
    const svg = document.createElementNS(ns, 'svg')
    svg.setAttribute('viewBox', '0 0 16 16')
    svg.setAttribute('width', '15')
    svg.setAttribute('height', '15')
    svg.setAttribute('fill', 'none')
    svg.setAttribute('stroke', 'currentColor')
    svg.setAttribute('stroke-width', '1.3')
    svg.setAttribute('stroke-linecap', 'round')
    svg.setAttribute('aria-hidden', 'true')

    const arc = document.createElementNS(ns, 'path')
    arc.setAttribute('d', 'M13.1 8a5.1 5.1 0 1 1-1.5-3.6')
    const head = document.createElementNS(ns, 'path')
    head.setAttribute('d', 'M13.3 2.9v3h-3')
    svg.append(arc, head)
    return svg
  }

  /**
   * One menu row, cloned from the anchor so it inherits the host's spacing,
   * hover and focus treatment.
   *
   * @param template - the row to clone.
   * @returns the empty row, still without copy or handler.
   */
  function buildRow(template) {
    const row = template.cloneNode(false)
    row.setAttribute('data-dsh-restart-row', '')
    row.setAttribute('role', 'menuitem')
    row.setAttribute('tabindex', '-1')
    row.classList.add('dsh-restart-row')
    while (row.firstChild !== null) row.removeChild(row.firstChild)

    const icon = document.createElement('span')
    icon.className = 'dsh-restart-row-icon'
    icon.appendChild(glyphNode())

    const label = document.createElement('span')
    label.className = 'dsh-restart-row-label'

    row.append(icon, label)
    return row
  }

  /**
   * Write the current state onto a row. Every write is guarded by a comparison:
   * the menu is rebuilt inside the same mutation sweep that watches it, so an
   * unconditional write would feed the observer its own output.
   *
   * @param row - the injected row.
   * @param t - bound translation.
   */
  function paint(row, t) {
    const label = row.querySelector('.dsh-restart-row-label')
    if (label === null) return
    const glyph = row.querySelector('.dsh-restart-row-icon svg')

    const busy = state.phase === 'busy'
    if (busy) {
      if (label.textContent !== t('menu.pending')) label.textContent = t('menu.pending')
      if (row.getAttribute('aria-disabled') !== 'true') row.setAttribute('aria-disabled', 'true')
      if (glyph !== null) glyph.classList.add('dsh-restart-row-spin')
      return
    }

    const next = state.error === null ? t('menu.label') : state.error
    if (label.textContent !== next) label.textContent = next
    if (row.hasAttribute('aria-disabled')) row.removeAttribute('aria-disabled')
    if (glyph !== null) glyph.classList.remove('dsh-restart-row-spin')
    if (state.error === null) {
      if (row.hasAttribute('title')) row.removeAttribute('title')
    } else {
      row.setAttribute('title', state.error)
    }
  }

  /**
   * Keep exactly one restart row in the open menu.
   *
   * @param t - bound translation.
   * @param press - the click handler.
   */
  function ensureRow(t, press) {
    const menu = findAccountMenu()
    if (menu === null) return

    const existing = menu.querySelector('[data-dsh-restart-row]')
    if (existing !== null) {
      paint(existing, t)
      return
    }

    const anchor = findAnchorRow(menu)
    if (anchor === null) return
    const wrap = anchor.parentNode
    if (wrap === null) return

    const row = buildRow(anchor)
    row.addEventListener('click', (event) => {
      event.preventDefault()
      event.stopPropagation()
      press()
    })
    paint(row, t)
    wrap.insertBefore(row, anchor)
  }

  /**
   * Install the row.
   *
   * The locale and session services are waited for here rather than declared on
   * the plugin, so a composition without them leaves this component inert and
   * the rest of the suite running.
   *
   * @param scope - client context with `locale` and `uiSession`.
   */
  function install(scope) {
    rt.style('restart', STYLESHEET)

    scope.effect(() => scope.locale.register(NS, { zh, en }), 'ui-copy/restart: dictionaries')

    const bind = scope.locale.bind(NS)

    /** The session currently occupying the main view, if any. */
    const currentSessionId = () => {
      try {
        return scope.uiSession?.current?.getSnapshot?.()?.key
      } catch {
        return undefined
      }
    }

    /**
     * Ask the host to quit and relaunch the app.
     *
     * @returns resolution once the host accepted the request.
     * @throws when the request could not be sent or the host refused it.
     */
    const restart = async () => {
      let response
      try {
        response = await fetch(RESTART_ROUTE, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ sessionId: currentSessionId() }),
          credentials: 'same-origin',
        })
      } catch {
        throw new Error(bind('failed.network'))
      }

      let payload = null
      try {
        payload = await response.json()
      } catch {
        // A body-less failure keeps its status-only verdict below.
      }

      if (!response.ok || payload === null || payload.ok !== true) {
        throw new Error(payload !== null && payload.reason === 'not-desktop' ? bind('failed.desktop') : bind('failed.generic'))
      }
      return payload
    }

    /** Start the restart; the row reads its own busy and error state. */
    const press = () => {
      if (state.phase === 'busy') return
      state.phase = 'busy'
      state.error = null
      restart().catch((reason) => {
        state.phase = 'idle'
        state.error = reason instanceof Error ? reason.message : String(reason)
      })
    }

    rt.observe(() => {
      // The runtime drops a pass that throws, so one bad frame must not cost the
      // menu row for the rest of the page's life.
      try {
        ensureRow(bind, press)
      } catch (error) {
        rt.warn('restart menu row failed: ' + String((error && error.message) || error))
      }
    })
  }

  rt.ctx.inject(['locale', 'uiSession'], (scope) => install(scope))
}

/* ---- entry ------------------------------------------------------------ */

window.__ModuleLoader__.load({
  // The boot-graph row id is the package name; client-modules serves this file
  // at `/plugins/<包名>/client.js` and keys the factory by the same string.
  id: 'dsh-ui-restart',
  factory: (require) => {
    const module = { exports: {} }
    const exports = module.exports
    Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' })

    /**
     * Mount this package's component on its own runtime.
     *
     * The host half injects this row's configuration as `window.DSHUI_RESTART`
     * before the boot graph runs, because a boot-graph row arrives as
     * `{ id, url, rev }` and `apply(ctx, config)` always sees an empty config.
     */
    function apply(ctx) {
      const injected = window.DSHUI_RESTART
      const config = typeof injected === 'object' && injected !== null ? injected : {}
      const runtime = dshuiCreateRuntime({ ctx, require }, { 'restart': config })
      runtime.mount('restart', dshuiComponent_restart)
      exports.runtime = runtime
      return function dispose() {
        runtime.dispose()
      }
    }

    exports.apply = apply
    exports.inject = []
    return module.exports
  },
})
